"""Public account API response boundary."""

from __future__ import annotations

import json
from typing import Any

# Allowlist, not a blocklist: new account fields (tokens, hashes, secrets)
# stay hidden from the public API by default until explicitly exposed here.
PUBLIC_ACCOUNT_FIELDS = ("id", "username", "display_name", "avatar_url", "created_at")


def serialize_account(account: dict[str, Any]) -> bytes:
    payload = {field: account[field] for field in PUBLIC_ACCOUNT_FIELDS if field in account}
    return json.dumps(payload, sort_keys=True).encode("utf-8")
